SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='pomodoro_room_messages' AND column_name='message_type')=0, 'ALTER TABLE pomodoro_room_messages ADD COLUMN message_type ENUM(''text'',''image'') NOT NULL DEFAULT ''text'' AFTER user_uid', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='pomodoro_room_messages' AND column_name='attachment_path')=0, 'ALTER TABLE pomodoro_room_messages ADD COLUMN attachment_path VARCHAR(255) NULL AFTER message', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
